const crypto = require('crypto');

const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

const signatureHeader = headers['x-rax-signature'];
const timestampHeader = headers['x-rax-timestamp'];
const rawBodyStr = JSON.stringify(body);

// 1. Validar presencia de cabeceras
if (!signatureHeader || !timestampHeader) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: 'Missing security headers (x-rax-signature, x-rax-timestamp)'
    }
  }];
}

// 2. Validar ventana de tiempo (anti-replay <= 300s)
const now = Math.floor(Date.now() / 1000);
const reqTime = parseInt(timestampHeader, 10);
if (isNaN(reqTime) || Math.abs(now - reqTime) > 300) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: 'Request timestamp expired or out of allowed window (300s)'
    }
  }];
}

// 3. Validar firma HMAC-SHA256
const secret = $env.RAX_N8N_SHARED_SECRET || 'test-shared-secret-rax-n8n';
const hmac = crypto.createHmac('sha256', secret);
const expectedSig = 'sha256=' + hmac.update(`${timestampHeader}.${rawBodyStr}`).digest('hex');

if (signatureHeader !== expectedSig) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: 'Invalid HMAC signature'
    }
  }];
}

// 4. Validar esquema mínimo de evento
if (!body.eventId || !body.eventType || !body.actor || !body.correlationId) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: 'Invalid event schema: missing eventId, eventType, actor or correlationId'
    }
  }];
}

return [{
  json: {
    valid: true,
    statusCode: 202,
    event: body,
    correlationId: body.correlationId,
    eventType: body.eventType
  }
}];
